import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.e4u2V5E7.js";const m=JSON.parse('{"title":"Workspace Maintenance Playbook","description":"Engineering playbook for workspace maintenance workflow","frontmatter":{"title":"Workspace Maintenance Playbook","description":"Engineering playbook for workspace maintenance workflow"},"headers":[],"relativePath":"playbooks/workspace-maintenance.md","filePath":"playbooks/workspace-maintenance.md","lastUpdated":1784485118000}'),r={name:"playbooks/workspace-maintenance.md"};function n(s,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="workspace-maintenance-playbook" tabindex="-1">Workspace Maintenance Playbook <a class="header-anchor" href="#workspace-maintenance-playbook" aria-label="Permalink to &quot;Workspace Maintenance Playbook&quot;">​</a></h1><h1 id="playbook-workspace-maintenance" tabindex="-1">Playbook: Workspace Maintenance <a class="header-anchor" href="#playbook-workspace-maintenance" aria-label="Permalink to &quot;Playbook: Workspace Maintenance&quot;">​</a></h1><p><strong>Goal:</strong> Keep the OpenCode workspace healthy, consistent, and up to date.</p><p><strong>Trigger:</strong> Weekly maintenance, after bulk changes, workspace issues, onboarding.</p><p><strong>Inputs:</strong></p><ul><li>Maintenance type (routine, post-change, issue-fix)</li><li>Scope (full workspace, specific area)</li></ul><p><strong>Outputs:</strong></p><ul><li>Health report</li><li>Fixed issues</li><li>Updated manifests</li><li>Optimization recommendations</li></ul><p>----|------| | <code>context-engineer</code> | Primary — workspace health, AGENTS.md | | <code>reviewer</code> | Quality review of workspace files | | <code>security</code> | Security audit of workspace |</p><h2 id="required-skills" tabindex="-1">Required Skills <a class="header-anchor" href="#required-skills" aria-label="Permalink to &quot;Required Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>When to Load</th></tr></thead><tbody><tr><td><code>validate-workspace</code></td><td>Always — full validation</td></tr><tr><td><code>agent-design</code></td><td>If creating/fixing agents</td></tr><tr><td><code>skill-design</code></td><td>If creating/fixing skills</td></tr><tr><td><code>workspace-optimization</code></td><td>Workspace improvements</td></tr></tbody></table><h2 id="required-commands" tabindex="-1">Required Commands <a class="header-anchor" href="#required-commands" aria-label="Permalink to &quot;Required Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>When to Use</th></tr></thead><tbody><tr><td><code>/health-check</code></td><td>Always — workspace health</td></tr><tr><td><code>/workspace-audit</code></td><td>Deep audit</td></tr><tr><td><code>/workspace-validate</code></td><td>Validation checks</td></tr></tbody></table><hr><h2 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h2><h3 id="step-1-health-check-10-min" tabindex="-1">Step 1: Health Check (10 min) <a class="header-anchor" href="#step-1-health-check-10-min" aria-label="Permalink to &quot;Step 1: Health Check (10 min)&quot;">​</a></h3><ol><li><strong>Run <code>/health-check</code></strong> — Full workspace validation</li><li><strong>Review report</strong> — Identify issues</li><li><strong>Prioritize</strong> — Critical first, then warnings</li></ol><h3 id="step-2-fix-issues-varies" tabindex="-1">Step 2: Fix Issues (varies) <a class="header-anchor" href="#step-2-fix-issues-varies" aria-label="Permalink to &quot;Step 2: Fix Issues (varies)&quot;">​</a></h3><ol><li><strong>Duplicate components</strong> — Remove or merge</li><li><strong>Broken references</strong> — Fix cross-references</li><li><strong>Missing metadata</strong> — Add required fields</li><li><strong>Weak implementations</strong> — Strengthen to production quality</li><li><strong>Naming problems</strong> — Fix to match conventions</li><li><strong>Empty documentation</strong> — Fill or remove</li></ol><h3 id="step-3-synchronize-10-min" tabindex="-1">Step 3: Synchronize (10 min) <a class="header-anchor" href="#step-3-synchronize-10-min" aria-label="Permalink to &quot;Step 3: Synchronize (10 min)&quot;">​</a></h3><ol><li><strong>Update MANIFEST.md</strong> — Reflect current state</li><li><strong>Update AGENTS.md</strong> — Manifest section</li><li><strong>Update dependency graph</strong> — Reflect changes</li><li><strong>Verify routing</strong> — All routes point correctly</li></ol><h3 id="step-4-optimize-10-min" tabindex="-1">Step 4: Optimize (10 min) <a class="header-anchor" href="#step-4-optimize-10-min" aria-label="Permalink to &quot;Step 4: Optimize (10 min)&quot;">​</a></h3><ol><li><strong>Remove unused components</strong> — Clean orphaned files</li><li><strong>Merge overlapping skills</strong> — Consolidate similar skills</li><li><strong>Strengthen weak skills</strong> — Improve quality</li><li><strong>Update templates</strong> — Keep templates current</li></ol><h3 id="step-5-document-5-min" tabindex="-1">Step 5: Document (5 min) <a class="header-anchor" href="#step-5-document-5-min" aria-label="Permalink to &quot;Step 5: Document (5 min)&quot;">​</a></h3><ol><li><strong>Update changelog</strong> — Record changes</li><li><strong>Update version</strong> — If significant changes</li><li><strong>Update roadmap</strong> — If new needs identified</li></ol><hr><h2 id="validation-steps" tabindex="-1">Validation Steps <a class="header-anchor" href="#validation-steps" aria-label="Permalink to &quot;Validation Steps&quot;">​</a></h2><ul><li>[ ] <code>/health-check</code> passes</li><li>[ ] No duplicate components</li><li>[ ] All cross-references valid</li><li>[ ] All metadata complete</li><li>[ ] Manifests are current</li><li>[ ] Naming conventions followed</li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>Workspace health check passes</li><li>No critical issues</li><li>Manifests are accurate</li><li>Workspace is optimized</li></ul><h2 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Why It&#39;s Wrong</th><th>Correct Approach</th></tr></thead><tbody><tr><td>Skipping regular maintenance</td><td>Issues accumulate</td><td>Run weekly</td></tr><tr><td>Not re-validating after fixes</td><td>Fixes may not work</td><td>Always re-run health check</td></tr><tr><td>Ignoring warnings</td><td>They become critical</td><td>Address promptly</td></tr><tr><td>Not updating manifests</td><td>Outdated information</td><td>Always sync manifests</td></tr></tbody></table><h2 id="related-commands" tabindex="-1">Related Commands <a class="header-anchor" href="#related-commands" aria-label="Permalink to &quot;Related Commands&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/commands/">Commands Registry</a> for commands used in this playbook.</p><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents involved in this playbook.</p>',36)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
